const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');

// Read migration files from ./migrations/ directory
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.log('Migrations directory does not exist. Creating it...');
    fs.mkdirSync(migrationsDir, { recursive: true });
    return [];
  }

  // Read directory contents
  const files = fs.readdirSync(migrationsDir);

  // Filter for SQL files only
  const sqlFiles = files.filter(file => file.endsWith('.sql'));

  // Sort files alphabetically to ensure correct order
  sqlFiles.sort();

  return sqlFiles;
}

// Main migration function
function runMigrations() {
  console.log('Reading migrations from ./migrations/ directory...\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  // Log each filename that would be applied, in order
  migrationFiles.forEach((filename, index) => {
    console.log(`${index + 1}. ${filename}`);
  });
}

// Run the migration script
runMigrations();

