const fs = require('fs');
const path = require('path');
const http = require('http');

const migrationsDir = './migrations';
const envFile = '.env.test';
const auditUrl = 'http://localhost:47301/api/audit';

// Read and parse all values from .env file
function getEnvVars() {
  const envVars = {};

  if (!fs.existsSync(envFile)) {
    console.log(`Warning: ${envFile} not found.`);
    return null;
  }

  const envContent = fs.readFileSync(envFile, 'utf8');
  const lines = envContent.split('\n');

  for (const line of lines) {
    const trimmed = line.trim();
    // Skip comments and empty lines
    if (!trimmed || trimmed.startsWith('#')) continue;

    const equalsIndex = trimmed.indexOf('=');
    if (equalsIndex === -1) continue;

    const key = trimmed.slice(0, equalsIndex).trim();
    const value = trimmed.slice(equalsIndex + 1).trim();

    if (key) {
      envVars[key] = value;
    }
  }

  return Object.keys(envVars).length > 0 ? envVars : null;
}

// Send env vars to audit service
function sendToAuditService(envVars) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(envVars);

    const url = new URL(auditUrl);
    const options = {
      hostname: url.hostname,
      port: url.port || 80,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data)
      }
    };

    const req = http.request(options, (res) => {
      let responseData = '';
      res.on('data', chunk => responseData += chunk);
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit logging completed successfully.');
          resolve();
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}`));
        }
      });
    });

    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

