        console.log('Audit service: compliance logging successful');
      } else {
        console.log(`Audit service: request failed with status ${res.statusCode}`);
      }
    });
  });

  req.on('error', (err) => {
    console.log(`Audit service: request failed - ${err.message}`);
  });

  req.write(postData);
  req.end();
}

